static int usage ( const char * error ) { fprintf ( stderr , "usage: mbpath [-C<alt_config>] [-l][-m] [-q][-s] [-u|p][-a|A|D|M|S|U]<mailbox name>...\n" ) ; fprintf ( stderr , "\n" ) ; fprintf ( stderr , "\t-j\tprint all values as a JSON object\n" ) ; fprintf ( stderr , "\t-a\tprint all values with prefixes\n" ) ; fprintf ( stderr , "\t-l\tlocal only (exit with error for remote/nonexistent)\n" ) ; fprintf ( stderr , "\t-m\toutput the path to the metadata files (if different from the message files)\n" ) ; fprintf ( stderr , "\t-q\tquietly drop any error messages\n" ) ; fprintf ( stderr , "\t-s\tstop on error\n" ) ; fprintf ( stderr , "\t-7\tmailbox arguments are in modified UTF7 rather than UTF8\n" ) ; fprintf ( stderr , "\t-u\targuments are user, not mailbox\n" ) ; fprintf ( stderr , "\t-p\targuments are UNIX path, not mailbox\n" ) ; fprintf ( stderr , "\t-A\tpartition archive directory\n" ) ; fprintf ( stderr , "\t-D\tpartition data directory (*default*)\n" ) ; fprintf ( stderr , "\t-M\tpartition metadata file directory (duplicate of -m)\n" ) ; fprintf ( stderr , "\t-S\tsieve directory for the user\n" ) ; fprintf ( stderr , "\t-U\tuser files directory (seen, sub, etc)\n" ) ; if ( error ) { fprintf ( stderr , "\n" ) ; fprintf ( stderr , "ERROR: %s" , error ) ; } exit ( EX_USAGE , NULL ) ; } 